using System;
using System.Reflection;
using UnityEditor;
using UnityEditor.XR.Management;
using UnityEditor.XR.Management.Metadata;
using UnityEngine;
using UnityEngine.XR.Management;

namespace DiyVr.EditorTools
{
    /// <summary>
    /// Enables the ARCore XR loader for Android and sets ARCore to Required with Depth optional.
    /// XR settings assets carry package-internal GUIDs, so they are generated by the editor on first
    /// load instead of being written by hand. Idempotent. CI can also call
    /// DiyVr.EditorTools.ProjectSetup.Configure via -executeMethod.
    /// </summary>
    public static class ProjectSetup
    {
        private const string ArCoreLoader = "UnityEngine.XR.ARCore.ARCoreLoader";

        [InitializeOnLoadMethod]
        private static void OnLoad()
        {
            EditorApplication.delayCall += () =>
            {
                try { Configure(); }
                catch (Exception e) { Debug.LogWarning("DIY VR project setup failed: " + e); }
            };
        }

        public static void Configure()
        {
            EnableArCoreLoader();
            ConfigureArCoreSettings();
            UpgradeUrpAsset();
            EnsureArBackgroundFeature();
            // ARCore's build step rejects Vulkan, so Android uses OpenGLES3 only.
            PlayerSettings.SetUseDefaultGraphicsAPIs(UnityEditor.BuildTarget.Android, false);
            PlayerSettings.SetGraphicsAPIs(UnityEditor.BuildTarget.Android,
                new[] { UnityEngine.Rendering.GraphicsDeviceType.OpenGLES3 });
            // Swappy (Optimized Frame Pacing) can hold the app at the display's current rate; off lets 120 Hz through.
            PlayerSettings.Android.optimizedFramePacing = false;
            AssetDatabase.SaveAssets();
        }

        // The URP asset was hand-written with a guessed k_AssetVersion; the URP build step refuses assets
        // that are not at the package's last version. Read that version from the package and stamp it.
        private static void UpgradeUrpAsset()
        {
            var type = Type.GetType("UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset, Unity.RenderPipelines.Universal.Runtime");
            if (type == null) { Debug.LogWarning("URP asset type not found"); return; }
            var field = type.GetField("k_LastVersion", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
            if (field == null) { Debug.LogWarning("URP k_LastVersion not found"); return; }
            var last = Convert.ToInt32(field.GetRawConstantValue());
            Debug.Log("URP k_LastVersion = " + last);
            foreach (var guid in AssetDatabase.FindAssets("t:UniversalRenderPipelineAsset"))
            {
                var asset = AssetDatabase.LoadMainAssetAtPath(AssetDatabase.GUIDToAssetPath(guid));
                if (asset == null) continue;
                var so = new SerializedObject(asset);
                var v = so.FindProperty("k_AssetVersion");
                var pv = so.FindProperty("k_AssetPreviousVersion");
                if (v == null) continue;
                v.intValue = last;
                if (pv != null) pv.intValue = last;
                so.ApplyModifiedPropertiesWithoutUndo();
                EditorUtility.SetDirty(asset);
            }
        }

        // Passthrough turns on an ARCameraBackground, and under URP that component draws only when the renderer has
        // ARBackgroundRendererFeature. Add it to the renderer asset if missing. The feature only acts on cameras that
        // have an enabled ARCameraBackground, which exists only while passthrough is shown. Idempotent.
        private const string RendererAssetPath = "Assets/Settings/MobileURP_Renderer.asset";

        private static void EnsureArBackgroundFeature()
        {
            var featureType = Type.GetType("UnityEngine.XR.ARFoundation.ARBackgroundRendererFeature, Unity.XR.ARFoundation");
            if (featureType == null) { Debug.LogWarning("ARBackgroundRendererFeature type not found"); return; }
            var renderer = AssetDatabase.LoadMainAssetAtPath(RendererAssetPath);
            if (renderer == null) { Debug.LogWarning("URP renderer asset not found at " + RendererAssetPath); return; }

            var so = new SerializedObject(renderer);
            var features = so.FindProperty("m_RendererFeatures");
            var map = so.FindProperty("m_RendererFeatureMap");
            if (features == null || map == null) { Debug.LogWarning("URP renderer feature lists not found"); return; }
            for (int i = 0; i < features.arraySize; i++)
            {
                var existing = features.GetArrayElementAtIndex(i).objectReferenceValue;
                if (existing != null && featureType.IsInstanceOfType(existing)) return;
            }

            var feature = ScriptableObject.CreateInstance(featureType);
            feature.name = "ARBackgroundRendererFeature";
            AssetDatabase.AddObjectToAsset(feature, renderer);
            if (!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(feature, out string _, out long localId))
                throw new InvalidOperationException("Could not read the file id of the new renderer feature");

            features.arraySize++;
            features.GetArrayElementAtIndex(features.arraySize - 1).objectReferenceValue = feature;
            map.arraySize++;
            map.GetArrayElementAtIndex(map.arraySize - 1).longValue = localId;
            so.ApplyModifiedPropertiesWithoutUndo();
            EditorUtility.SetDirty(renderer);
            AssetDatabase.SaveAssets();
            Debug.Log("Added ARBackgroundRendererFeature to " + RendererAssetPath);
        }

        private static void EnableArCoreLoader()
        {
            var group = BuildTargetGroup.Android;
            if (!EditorBuildSettings.TryGetConfigObject(XRGeneralSettings.k_SettingsKey,
                    out XRGeneralSettingsPerBuildTarget perBuild))
            {
                perBuild = ScriptableObject.CreateInstance<XRGeneralSettingsPerBuildTarget>();
                if (!AssetDatabase.IsValidFolder("Assets/XR")) AssetDatabase.CreateFolder("Assets", "XR");
                AssetDatabase.CreateAsset(perBuild, "Assets/XR/XRGeneralSettingsPerBuildTarget.asset");
                EditorBuildSettings.AddConfigObject(XRGeneralSettings.k_SettingsKey, perBuild, true);
            }

            if (!perBuild.HasManagerSettingsForBuildTarget(group))
                perBuild.CreateDefaultManagerSettingsForBuildTarget(group);

            var manager = perBuild.ManagerSettingsForBuildTarget(group);
            if (!XRPackageMetadataStore.AssignLoader(manager, ArCoreLoader, group))
                throw new InvalidOperationException("Could not assign " + ArCoreLoader);
            EditorUtility.SetDirty(perBuild);
        }

        private static void ConfigureArCoreSettings()
        {
            // ARCoreSettings lives in a package editor assembly; find the asset by type name instead of
            // reflecting a type path. Assigning the loader already creates it under Assets/XR/Settings.
            UnityEngine.Object settings = null;
            foreach (var guid in AssetDatabase.FindAssets("t:ARCoreSettings"))
            {
                settings = AssetDatabase.LoadMainAssetAtPath(AssetDatabase.GUIDToAssetPath(guid));
                if (settings != null) break;
            }
            if (settings == null)
                throw new InvalidOperationException("No ARCoreSettings asset found");

            var so = new SerializedObject(settings);
            var names = new System.Text.StringBuilder();
            var it = so.GetIterator();
            for (bool next = it.NextVisible(true); next; next = it.NextVisible(false))
                names.Append(it.propertyPath).Append(',');
            Debug.Log("ARCoreSettings fields: " + names);

            SetEnum(so, "m_Requirement", 0); // Required
            SetEnum(so, "m_Depth", 1);       // Optional
            so.ApplyModifiedPropertiesWithoutUndo();
            EditorUtility.SetDirty(settings);
        }

        private static void SetEnum(SerializedObject so, string name, int value)
        {
            var p = so.FindProperty(name);
            if (p == null) throw new InvalidOperationException("ARCoreSettings has no field " + name);
            p.enumValueIndex = value;
        }
    }
}
